	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void packedStarExecutesWhenSubjectDomainsDoOrDoNotOverlap(boolean overlap) {
		String property = "rdf4j.lmdb.nativeQueryEngine.enabled";
		String previous = System.setProperty(property, "true");
		LmdbStore store = new LmdbStore(dataDir.toFile(), new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (SailRepositoryConnection connection = repository.getConnection()) {
				ValueFactory vf = connection.getValueFactory();
				connection.begin();
				connection.add(vf.createIRI("urn:star:a"), vf.createIRI("urn:star:p"), vf.createIRI("urn:star:x"));
				connection.add(vf.createIRI(overlap ? "urn:star:a" : "urn:star:b"),
						vf.createIRI("urn:star:q"), vf.createIRI("urn:star:y"));
				connection.commit();
			}
			assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
			try (SailRepositoryConnection connection = repository.getConnection()) {
				SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(
						"SELECT ?s ?x ?y WHERE { ?s <urn:star:p> ?x . ?s <urn:star:q> ?y }");
				query.setForcedLmdbExecutionStrategy("packedFtree(serial)");
				GenericPlanNode plan = query.explain(Explanation.Level.Telemetry).toGenericPlanNode();
				assertThat(metric(plan, LmdbNativeExplain.EXECUTION_PATH)).isEqualTo("packedFtree(serial)");
				AtomicReference<LmdbNativeCostVector> physical = observePackedQuote();
				try (TupleQueryResult result = query.evaluate()) {
					assertThat(result.hasNext()).isEqualTo(overlap);
					if (overlap) {
						result.next();
						assertThat(result.hasNext()).isFalse();
					}
				} finally {
					LmdbNativeDispatchLoop.observeSelections(null);
				}
				assertThat(physical.get()).isNotNull();
				if (!overlap) {
					// One exact root and at most one matching child lane can be built for disjoint domains.
					assertThat(physical.get().low(Feature.BATCH_ROW)).isBetween(1D, 2D);
				}
			}
		} finally {
			repository.shutDown();
			if (previous == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, previous);
			}
		}
	}

	@Test
	void packedLaneCeilingIncludesSkewedSubjectFanOut() {
		String property = "rdf4j.lmdb.nativeQueryEngine.enabled";
		String borrowing = "rdf4j.lmdb.factor.borrowed.enabled";
		String previous = System.setProperty(property, "true");
		String previousBorrowing = System.setProperty(borrowing, "false");
		LmdbStore store = new LmdbStore(dataDir.toFile(), new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (SailRepositoryConnection connection = repository.getConnection()) {
				ValueFactory vf = connection.getValueFactory();
				connection.begin();
				for (int subject = 0; subject < 10; subject++) {
					var s = vf.createIRI("urn:skew:s" + subject);
					if (subject < 2) {
						connection.add(s, vf.createIRI("urn:skew:p"), vf.createIRI("urn:skew:x"));
					}
					int degree = subject < 2 ? 6 : 1;
					for (int object = 0; object < degree; object++) {
						connection.add(s, vf.createIRI("urn:skew:q"), vf.createIRI("urn:skew:y" + object));
					}
				}
				connection.commit();
			}
			assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
			try (SailRepositoryConnection connection = repository.getConnection()) {
				SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(
						"SELECT ?s ?x ?y WHERE { ?s <urn:skew:p> ?x . ?s <urn:skew:q> ?y }");
				query.setForcedLmdbExecutionStrategy("packedFtree(serial)");
				AtomicReference<LmdbNativeCostVector> physical = observePackedQuote();
				int rows = 0;
				try (TupleQueryResult result = query.evaluate()) {
					while (result.hasNext()) {
						result.next();
						rows++;
					}
				} finally {
					LmdbNativeDispatchLoop.observeSelections(null);
				}
				assertThat(rows).isEqualTo(12);
				assertThat(physical.get()).isNotNull();
				// Each of the twelve matching q edges needs a packed lane, whatever root the planner chooses.
				// The q predicate's global mean is two, but the two participating subjects each have six.
				assertThat(physical.get().high(Feature.BATCH_ROW)).isGreaterThanOrEqualTo(12D);
			}
		} finally {
			repository.shutDown();
			restoreProperty(property, previous);
			restoreProperty(borrowing, previousBorrowing);
		}
	}

	private static AtomicReference<LmdbNativeCostVector> observePackedQuote() {
		AtomicReference<LmdbNativeCostVector> physical = new AtomicReference<>();
		LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
			if (id.equals("packedFtree(serial)")) {
				physical.set(record.entries().get(record.winner()).features());
			}
		});
		return physical;
	}

	private static void restoreProperty(String property, String previous) {
		if (previous == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, previous);
		}
	}

	private static String metric(GenericPlanNode node, String name) {
		String value = node.getStringMetricActual(name);
		if (value != null) {
			return value;
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				String found = metric(child, name);
				if (found != null) {
					return found;
				}
			}
		}
		return null;
	}

	@Test
	void descriptionsCoverNestedJoinsAndUnionsWithoutInventingFloors() {
		StatsSource source = new StatsSource(100_000L).predicate(1L, 3D, 3_000L)
				.predicate(2L, 3D, 3_000L)
				.adjacencyServed(true);
		RowState row = row(source);
		SlotPlan join = new JoinPlan(edge(0, 1L, 1, 9_000D), edge(0, 2L, 2, 9_000D));
		SlotPlan union = new UnionPlan(join, EmptyPlan.INSTANCE);
		NativeAggregateCostQuotes.Input input = NativeAggregateCostQuotes.describe(union, row, 0L);
		assertThat(input).isNotNull();
		assertThat(input.rows()).isPositive();
		assertThat(input.lowRows()).isZero();
		assertThat(input.operations().expected(Feature.SCANNED_ROW)).isPositive();
		assertThat(input.highRows()).isGreaterThanOrEqualTo(input.rows());
		assertThat(NativeAggregateCostQuotes.describe(EmptyPlan.INSTANCE, row, 0L).highRows()).isZero();
	}

	@Test
	void nestedLexicalExpressionsArePricedInBothSequentialAndKernelProfiles() {
		StatsSource source = new StatsSource(100_000L).predicate(1L, 3D, 3_000L).adjacencyServed(true);
		RowState row = row(source);
		SlotPlan input = edge(0, 1L, 1, 9_000D);
		SlotPlan copy = new ExtensionPlan(input, new CopyBinding[] { CopyBinding.slot(2, 1) });
		ValueExpr expression = new FunctionCall(FN.STRING_LENGTH.stringValue(),
				new FunctionCall(FN.LOWER_CASE.stringValue(), new Str(new Var("a"))));
		NativeScalarPlan scalar = NativeScalarPlan.value(expression, name -> name.equals("a") ? 1 : -1,
				false, 0L, false, false);
		assertThat(scalar).isNotNull();
		LmdbNativeCompiledValue evaluator = new LmdbNativeCompiledValue(1L << 1, ignored -> null, scalar);
		SlotPlan lexical = new ExtensionPlan(input,
				new CopyBinding[] { CopyBinding.computedValue(2, evaluator, true) });
		for (Mode mode : new Mode[] { Mode.SEQUENTIAL, Mode.KERNEL }) {
			LmdbNativeCostVector simple = LmdbNativePlanExecutionProfile.profile(copy, row, 0L, mode);
			LmdbNativeCostVector nested = LmdbNativePlanExecutionProfile.profile(lexical, row, 0L, mode);
			assertThat(nested.expected(Feature.INTERPRETED_ROW)).as("nested operations: %s", mode)
					.isGreaterThan(simple.expected(Feature.INTERPRETED_ROW));
			assertThat(nested.expected(Feature.DECODED_ROW)).as("lexical dictionary read: %s", mode)
					.isGreaterThan(simple.expected(Feature.DECODED_ROW));
		}
	}
